You are an expert mathematician. Your task is to provide a thorough and correct proof for a mathematical problem (your Target Problem). This proof will be used to benchmark your abilities as a mathematician.

To obtain your proof, you can assume and use any reference (lemma, theorem, definition, etc) from the context below:

********** BEGIN CONTEXT **********

Consider a probability distribution $\pi(x)$ defined on the $n$-dimensional hypercube $G=(V, E)$ where $V=\{0,1\}^n$ and two vertices $x$ and $y$ are connected when they differ only in one bit. This distribution is the unique stationary distribution of a Markov chain whose transition matrix includes additional self-loops and has the following entries:
 \begin{align}
P(x,y)=\begin{cases} 
       \frac{1}{n}\cdot \sum_{x':(x', x)\in E}\frac{\pi(x)}{\pi(x)+\pi(x')} & x=y,\\
       \frac{1}{n}\cdot \frac{\pi(y)}{\pi(x)+\pi(y)} & (x,y)\in E, \\
       0 & \text{otherwise}.
      \end{cases}\label{eq:TransitionMatrix-Haar}
\end{align}
Our goal is to analyze the spectral gap of the transition matrix $P$ when $\pi(x)$ is randomly chosen according to the Porter-Thomas distribution. That is, for any $x\in \{0,1\}^n$, we independently draw a sample $\bm{z}(x)$ from the exponential distribution $\Pr(\bm{z})=e^{-\bm{z}}\cdot \iden[\bm{z}\geq 0]$. We then set $\pi(x)=\frac{\bm{z}(x)}{2^n}$.

 \begin{proposition}[Tail bounds]\label{prop:concentration}
The following two tail bounds hold:
 \begin{enumerate}
     \item Let $\bm{x_1}, \dots, \bm{x_m}$ be $m$ i.i.d. Bernoulli random variables with $\Pr[\bm{x_i} = 1] = p$ for $i\in [m]$. There exist constants $\alpha, \beta > 0$ such that 
     \begin{align}
         \Pr\left(\sum_{i=1}^m \bm{x_i} \leq \alpha \cdot n\right)\leq 2^{-(1+\beta)n}.\label{eq:concentrationBin}
     \end{align}
     \item Suppose $\bm{z}_1,\dots,\bm{z}_m$ are drawn independently from the exponential distribution $\Pr(\bm{z})=e^{-\bm{z}}\cdot \iden[\bm{z}\geq 0]$. Then, the following two-sided concentration bound holds:
     \begin{align}
         \Pr\left(\left|\frac{1}{m}\sum_{k=1}^m \bm{z}_k - 1\right|\geq t \right)\leq
         \begin{cases}
             2e^{-\frac{m t^2}{8}} & 0\leq t\leq 2,\\
             2e^{-\frac{m t}{4}} & t\geq 2.
         \end{cases}\label{eq:concentrationSubExp}
     \end{align}
Moreover, for any $k$, we have
\begin{align}
    \Pr\left(\bm{z}_k\leq t\right)=1-e^{-t}\leq t \label{eq:CDFexp}
\end{align}
 \end{enumerate}

 \end{proposition}

\begin{proposition}\label{prop:nVertexConnectionHypercube}
For any two vertices $x,y \in \{0,1\}^n$ in the $n$-dimensional hypercube, there are $n$ simple pairwise internally disjoint paths connecting them such that no two paths share a vertex except for the starting and end vertices $x$ and $y$. Moreover, the length $|\g_{xy}|$ of all such paths is bounded by $n+1$. 
\end{proposition}

A set of canonical paths $\G$ in a graph $G$ is a collection of simple paths $\gamma_{xy}$, each connecting a unique pair of distinct vertices $(x,y)\in E$. Given a set of canonical paths, the path congestion parameter is defined by
\begin{align}
    \rho(\G):= \max_{e \in E} \frac{1}{Q(e)} \sum_{\g_{xy}\ni e} \pi(x)\pi(y) |\gamma_{xy}|
\end{align}
where for an edge $e=(e^+,e^-)$, its weight given by $Q(e)=\pi(e^{+})P(e^{+},e^{-})$ is the probability of the transition $(e^+,e^-)$ occurring in the random walk. 

Define the normalization factor $\bm{S}=\sum_{x\in \{0,1\}^n} \bm{z}(x)$. Assuming the set of canonical paths does not contain a self-loop, we can rewrite the path congestion as:
\begin{align}
    \bm{\rho}(\G):= \frac{n}{\bm{S}}\max_{e=(e^+,e^-)} \frac{\bm{z}_{e^+}+\bm{z}_{e^-}}{\bm{z}_{e^+}\bm{z}_{e^-}} \sum_{\g_{xy}\ni e} \bm{z}(x)\bm{z}(y) |\gamma_{xy}|.\label{eq:congestionRewrite}
\end{align}

We partition the vertices into two sets of `bad' and `good' vertices $\bm{V_{\mathrm{bad}}}:=\{x\in \{0,1\}^n: \bm{z}(x)\leq 1/(64n)\}$ and $\bm{V_{\mathrm{good}}}:=V\setminus \bm{V_{\mathrm{bad}}}$.

\begin{lemma}\label{lem:propertiesofCanonicalPaths}
    Except for probability $\leq 2^{-3n}$, there exists a set of canonical paths $\G=\{\g_{xy}\}$ with the following properties:
    \begin{enumerate}
    \item All paths are simple and without self-loops.
    \item The length of each path is bounded by $|\g_{xy}|\leq n+3$. 
        \item A bad vertex in $\bm{V_{\mathrm{bad}}}$ that is part of a canonical path can only be the starting or the end point of the path. 
\end{enumerate}
    \end{lemma}


********** END CONTEXT **********

