\begin{proof}[Proof of \thmref{upperBoundCongestion}]
We upper bound the path congestion parameter $\bm{\r}(\G)$ for any edge $e=(e^+,e^-)$ that participates in a path in separate cases. From property 3. of \lemref{propertiesofCanonicalPaths}, we have that if both $e^+$ and $e^-$ are bad vertices in $\bm{V_{\mathrm{bad}}}$, then the edge $(e^+,e^-)$ is not part of any canonical path. 
Next, suppose $e^+ \in \bm{V_{\mathrm{bad}}}$ while $e^-\in \bm{V_{\mathrm{good}}}$ (the case of $e^-$ being bad instead is similar). This implies that $\bm{z}_{e^+}\leq \bm{z}_{e^-}$. Following Equation \eqref{eq:congestionRewrite}, we bound the quantity
\begin{align}
  &\frac{n}{\bm{S}}\cdot \frac{\bm{z}_{e^+}+\bm{z}_{e^-}}{\bm{z}_{e^+}\bm{z}_{e^-}} \sum_{\g_{xy}\ni e} \bm{z}(x)\bm{z}(y) |\gamma_{xy}|\\
  &=  \frac{n}{\bm{S}}\cdot\frac{\bm{z}_{e^+}+\bm{z}_{e^-}}{\bm{z}_{e^+}\bm{z}_{e^-}} \sum_{y \in \{0,1\}^n: y\neq e^+} \bm{z}(e^+)\bm{z}(y) |\gamma_{e^+y}|\nn\\
  &\leq \frac{2n}{\bm{S}}  \sum_{y \in \{0,1\}^n: y\neq e^+} \bm{z}(y) |\gamma_{e^+y}| && \text{$e^-\in \bm{V_{\mathrm{good}}}$ and $\bm{z}_{e^+}\leq \bm{z}_{e^-}$}\nn\\
  &\leq \frac{2n(n+3)}{\bm{S}}\cdot  \sum_{y \in \{0,1\}^n: y\neq e^+} \bm{z}(y)  && \text{Property 2. \lemref{propertiesofCanonicalPaths}}\nn\\
  &\leq \frac{2n(n+3)}{\bm{S}}\cdot  \sum_{y \in \{0,1\}^n} \bm{z}(y) \nn\\
   &\leq 2n(n+3).\label{eq:congestionboundcase1}
\end{align}
Now we consider the last case, when $e^+$ and $e^-$ are both good vertices in $\bm{V_{\mathrm{good}}}$.
We have
\begin{align}
  \frac{n}{\bm{S}}\cdot \frac{\bm{z}_{e^+}+\bm{z}_{e^-}}{\bm{z}_{e^+}\bm{z}_{e^-}} \sum_{\g_{xy}\ni e} \bm{z}(x)\bm{z}(y) |\gamma_{xy}|& \leq \frac{128n^2}{\bm{S}}\cdot\sum_{\g_{xy}\ni e} \bm{z}(x)\bm{z}(y) |\gamma_{xy}| && \bm{z}_{e^+} ,\bm{z}_{e^-} \in \bm{V_{\mathrm{good}}}\nn\\
  & \leq \frac{128n^2(n+3)}{\bm{S}}\cdot\sum_{\g_{xy}\ni e} \bm{z}(x)\bm{z}(y) && \text{Property 2. \lemref{propertiesofCanonicalPaths}}\label{eq:congestionboundcase2}
\end{align}
To upper bound the term $\sum_{\g_{xy}\ni e} \bm{z}(x)\bm{z}(y)$, recall that by the proof of \propref{nVertexConnectionHypercube}, for any canonical path $\g_{xy}$ between two good vertices $x,y \in \bm{V_{\mathrm{good}}}$, there exists an $i\in[n]$ such that $x$ and $y$ are connected first by flipping the $i$'th bit in $x$. 
Then, the bits of $x$ and $y$ are matched starting from the $i+1$'th bit and moving rightward and back to the $i$'th bit. 
For a fixed $i \in [n]$ and edge $e=(e^+, e^-)$, this procedure produces a set of paths (connecting different vertices)  that contain the edge $e=(e+,e-)$. 
We collectively denote such paths by $\G_i$.
We define $L_i$ (and $R_i \subseteq \{0,1\}^n$) to be the set of all starting (respectively end) vertices of the paths in $\G_i$. We have $|L_i|\cdot |R_i|\leq 2^n$ for all $i\in[n]$. 

Although for each pair of vertices, at most one of the $n$ paths generated by different choices of $i$ is used, we charitably upper bound $\sum_{\g_{xy}\ni e} \bm{z}(x)\bm{z}(y)$ by including all $n$ paths for any $x,y \in \{0,1\}^n$ including the bad vertices. Moreover, the bad vertices use a designated good neighbor to connect to other vertices. Again, we loosely upper bound this by multiplying the contribution of all vertices by a factor of $2$. Overall, we have
\begin{align}
  \frac{1}{\bm{S}} \cdot \sum_{\g_{xy}\ni e} \bm{z}(x)\bm{z}(y)\leq \frac{2^{n+2}}{\bm{S}} \cdot \sum_{i\in[n]} \left( \frac{1}{|L_i|}\sum_{x\in L_i} \bm{z}(x)\cdot \frac{1}{|R_i|}\sum_{y\in R_i}\bm{z}(y) \right)
\end{align}
Next, we apply the tail bound \eqref{eq:concentrationSubExp} in \propref{concentration} to $\bm{S}=\sum_{x\in \{0,1\}^n} \bm{z}(x)$ and also $\frac{1}{|L_i|}\sum_{x \in L_i} \bm{z}(x)$ and $\frac{1}{|R_i|} \sum_{x\in R_i} \bm{z}(x)$ for all $i\in [n]$.
We see that for a constant $c>1$, except with $\leq 2^{-3n}$ (or in fact up to a tighter bound $\leq 2^{-\Omega(n^c)}$), we have 
\begin{align}
     \text{when $i \in [c\cdot \log n, n- c\cdot\log n]$,\quad} \frac{1}{|L_i|}\sum_{x \in L_i} \bm{z}(x)\cdot \frac{1}{|R_i|} \sum_{x\in R_i} \bm{z}(x) \leq \mathcal{O}(1).
\end{align}
Similarly, with probability except with probability $2^{-3n}$, we have
\begin{align}
     \text{when $i \leq c\cdot \log n$ or $i \geq n - c\cdot \log n$,\quad} \frac{1}{|L_i|}\sum_{x \in L_i} \bm{z}(x)\cdot \frac{1}{|R_i|} \sum_{x\in R_i} \bm{z}(x) \leq \mathcal{O}(n).
\end{align}
Together, these bounds along with the concentration of $\bm{S} = \sum_{x \in \{0,1\}^n} \bm{z}(x)$ around $2^n$ imply that with probability $\geq 1 - 2^{-3n}$:
\begin{align}
   \frac{2^{n+2}}{\bm{S}}\cdot \sum_{i\in[n]} \left( \frac{1}{|L_i|}\sum_{x\in L_i} \bm{z}(x)\cdot \frac{1}{|R_i|}\sum_{y\in R_i}\bm{z}(y) \right) \leq \mathcal{O}(n\cdot \log n).
\end{align}
When combined with \eqref{eq:congestionboundcase2}, the following bound holds with probability $\geq 1-2^{-3n}$ for a fixed $e=(e^+,e^-)$:
\begin{align}
   \frac{n}{\bm{S}}\cdot \frac{\bm{z}_{e^+}+\bm{z}_{e^-}}{\bm{z}_{e^+}\bm{z}_{e^-}} \sum_{\g_{xy}\ni e} \bm{z}(x)\bm{z}(y) |\gamma_{xy}|&\leq \mathcal{O}(n^4 \cdot \log n). \nn
\end{align}
This bound along with \eqref{eq:congestionboundcase1} shows that for all edges $e=(e^+,e^-)$ (whose number we upper bound by $2^{2n}$) the congestion parameter is upper bound by $\r(\G)\leq \mathcal{O}(n^4 \cdot \log n)$ with probability $\geq 1-2^{-n}$.
\end{proof}
